  <script>
    // 解析文段并提取各部分内容设置占位符
    function parseContentAndSetPlaceholder(customContent = null) {
      let rawContent = '';

      // 优先级：自定义内容 > 隐藏元素内容 > 默认提示
      if (customContent) {
        rawContent = customContent;
      } else {
        rawContent = document.querySelector('#rawContent')?.textContent?.trim() || '';
      }

      // 如果内容不为空且包含<phone>标签
      if (rawContent && rawContent.includes('<phone>')) {
        // 分割文段，获取<phone>以上和以下的部分
        const parts = rawContent.split('<phone>');
        const contentBeforePhone = parts[0].trim();
        const contentAfterPhone = parts[1] ? parts[1].trim() : '';

        // 设置占位符1：<phone>以上的内容
        const contentDiv = document.querySelector('.letter-container .content');
        if (contentDiv && contentBeforePhone) {
                  // 将各种引号内的文字设置为粉红色，同时保持换行格式
        let formattedContent = contentBeforePhone.replace(/\n/g, '<br>');
        // 匹配所有类型的引号：英文双引号、中文双引号、英文单引号、中文单引号、书名号、全角引号等
        formattedContent = formattedContent.replace(/"([^"]*)"|"([^"]*)"|'([^']*)'|'([^']*)'|「([^」]*)」|『([^』]*)』|‚([^‚]*)‚|„([^„]*)„|‹([^‹]*)›|«([^«]*)»|＂([^＂]*)＂|＇([^＇]*)＇/g, function(match) {
          return '<span style="color: #FF69B4; font-weight: bold;">' + match + '</span>';
        });
          contentDiv.innerHTML = formattedContent;

          // 强制重新渲染，确保橙色文字效果生效
          setTimeout(() => {
            contentDiv.style.display = 'none';
            contentDiv.offsetHeight; // 触发重新渲染
            contentDiv.style.display = '';
          }, 10);
        }
        window.placeholder1 = contentBeforePhone;

        // 解析<phone>后的内容，提取时间和日期
        if (contentAfterPhone) {
          // 查找<Status>标签，分别处理<Status>之前和之后的内容
          let phoneContent = contentAfterPhone;
          let statusContent = '';

          if (contentAfterPhone.includes('<Status>')) {
            const statusParts = contentAfterPhone.split('<Status>');
            phoneContent = statusParts[0].trim();
            statusContent = statusParts[1] ? statusParts[1].trim() : '';
          }

          // 解析时间|日期格式 (例如: 23:15|2024-11-15)
          if (phoneContent.includes('|')) {
            const [timeStr, dateStr] = phoneContent.split('|').map(s => s.trim());

            // 设置占位符2：时间
            if (timeStr) {
              document.querySelectorAll('.status-time, .time-large').forEach(el => {
                el.textContent = timeStr;
              });
              window.placeholder2 = timeStr;
              console.log('占位符2已设置为时间:', timeStr);
            }

            // 设置占位符3：日期
            if (dateStr) {
              document.querySelectorAll('.date-small').forEach(el => {
                el.textContent = dateStr;
              });
              window.placeholder3 = dateStr;
              console.log('占位符3已设置为日期:', dateStr);
            }
          } else {
            // 如果没有|分隔符，尝试直接解析单行内容
            const lines = phoneContent.split('\n').filter(line => line.trim());
            if (lines.length >= 1) {
              // 第一行作为时间
              const timeStr = lines[0].trim();
              document.querySelectorAll('.status-time, .time-large').forEach(el => {
                el.textContent = timeStr;
              });
              window.placeholder2 = timeStr;
              console.log('占位符2已设置为时间:', timeStr);
            }
            if (lines.length >= 2) {
              // 第二行作为日期
              const dateStr = lines[1].trim();
              document.querySelectorAll('.date-small').forEach(el => {
                el.textContent = dateStr;
              });
              window.placeholder3 = dateStr;
              console.log('占位符3已设置为日期:', dateStr);
            }
          }

          // 解析<Status>后的内容
          if (statusContent) {
            parseStatusContent(statusContent);
          }

          // 解析整个contentAfterPhone中的<twitter>内容
