    // 专门解析Status标签的函数
    window.parseStatusData = function(statusContent) {
      console.log('开始解析Status数据:', statusContent);

      // 移除可能的</Status>结束标签
      let cleanContent = statusContent.replace(/<\/Status>/gi, '').trim();

      // 解析角色标签格式：<昕彤>数据<br>
      const characterData = {};

      // 查找所有角色标签
      const characterMatches = cleanContent.match(/<(昕彤|清韵|月绮|米尔可)>([^<]*?)(?:<br>|$)/g);

      if (characterMatches) {
        characterMatches.forEach(match => {
          // 提取角色名和数据
          const characterMatch = match.match(/<(昕彤|清韵|月绮|米尔可)>([^<]*?)(?:<br>|$)/);
          if (characterMatch) {
            const characterName = characterMatch[1];
            const data = characterMatch[2].split('|').map(item => item.trim());
            characterData[characterName] = data;
            console.log(`解析到${characterName}的数据:`, data);
          }
        });
      } else {
        // 兼容旧格式：按<br>分割的行格式
        const lines = cleanContent.split('<br>').map(line => line.trim()).filter(line => line);
        if (lines.length >= 1) {
          characterData['昕彤'] = lines[0].split('|').map(item => item.trim());
        }
        if (lines.length >= 2) {
          characterData['清韵'] = lines[1].split('|').map(item => item.trim());
        }
        if (lines.length >= 3) {
          characterData['月绮'] = lines[2].split('|').map(item => item.trim());
