    // 微信消息本地存储管理
    const WechatStorage = {
      key: 'wechatMessageGroups',
      maxGroups: 5,

      // 获取所有消息群
      getMessageGroups: function() {
        const stored = localStorage.getItem(this.key);
        return stored ? JSON.parse(stored) : [];
      },

      // 保存消息群
      saveMessageGroups: function(groups) {
        // 只保留最近5次消息群
        const limitedGroups = groups.slice(-this.maxGroups);
        localStorage.setItem(this.key, JSON.stringify(limitedGroups));
      },

      // 添加新消息群
      addMessageGroup: function(groupData) {
        const groups = this.getMessageGroups();
        groups.push({
          id: Date.now(),
          timestamp: new Date().toISOString(),
          messages: groupData.messages || [],
          userMessages: [] // 用户发送的消息
        });
        this.saveMessageGroups(groups);
      },

      // 添加用户消息到最新群
      addUserMessage: function(message) {
        const groups = this.getMessageGroups();
        if (groups.length > 0) {
          groups[groups.length - 1].userMessages.push({
            content: message,
            timestamp: new Date().toISOString()
          });
          this.saveMessageGroups(groups);
        }
      },

      // 获取最新消息群
      getLatestGroup: function() {
        const groups = this.getMessageGroups();
        return groups.length > 0 ? groups[groups.length - 1] : null;
      }
    };



    // 显示绿色气泡消息
    function addSentMessage(message) {
      const wechatContent = document.getElementById('wechatContent');
      if (!wechatContent) return;

      const messageDiv = document.createElement('div');
      messageDiv.className = 'wechat-message sent';

      messageDiv.innerHTML = `
        <div class="wechat-bubble">
          <div class="wechat-message-text">${message}</div>
        </div>
      `;

      wechatContent.appendChild(messageDiv);

      // 滚动到顶部（最新消息）
      setTimeout(() => {
        wechatContent.scrollTop = 0;
      }, 100);
    }

    // 发送微信消息的函数
    async function sendWechatMessage() {
      const message = wechatInput.value.trim();
      if (!message) return;

      try {
        // 添加绿色气泡显示
        addSentMessage(message);

        // 保存到本地存储
        WechatStorage.addUserMessage(message);

        const triggerRequest = `/trigger <Request: {{user}}通过微信发送消息：${message}>`;
        const sendRequest = `/send <Request: {{user}}通过微信发送消息：${message}>`;

        // 如果triggerSlash函数可用，使用它；否则输出到控制台
        if (typeof triggerSlash === 'function') {
          await triggerSlash(sendRequest);
          await triggerSlash(triggerRequest);
        } else {
          console.log('微信消息发送 send:', sendRequest);
          console.log('微信消息发送 trigger:', triggerRequest);
          // 可以在这里添加其他发送逻辑，比如显示在界面上
          // alert('微信消息已发送: ' + message);
        }

        // 清空输入框并隐藏发送按钮
        wechatInput.value = '';
        wechatSend.classList.remove('show');
      } catch (error) {
        console.error('发送微信消息时出错:', error);
      }
    }

