  <script>
    // 解析文段并提取各部分内容设置占位符
    function parseContentAndSetPlaceholder(customContent = null) {
      let rawContent = '';

      // 优先级：自定义内容 > 隐藏元素内容 > 默认提示
      if (customContent) {
        rawContent = customContent;
      } else {
        rawContent = document.querySelector('#rawContent')?.textContent?.trim() || '';
      }

      // 如果内容不为空且包含<phone>标签
      if (rawContent && rawContent.includes('<phone>')) {
        // 分割文段，获取<phone>以上和以下的部分
        const parts = rawContent.split('<phone>');
        const contentBeforePhone = parts[0].trim();
        const contentAfterPhone = parts[1] ? parts[1].trim() : '';

        // 设置占位符1：<phone>以上的内容
        const contentDiv = document.querySelector('.letter-container .content');
        if (contentDiv && contentBeforePhone) {
                  // 将各种引号内的文字设置为粉红色，同时保持换行格式
        let formattedContent = contentBeforePhone.replace(/\n/g, '<br>');
        // 匹配所有类型的引号：英文双引号、中文双引号、英文单引号、中文单引号、书名号、全角引号等
        formattedContent = formattedContent.replace(/"([^"]*)"|"([^"]*)"|'([^']*)'|'([^']*)'|「([^」]*)」|『([^』]*)』|‚([^‚]*)‚|„([^„]*)„|‹([^‹]*)›|«([^«]*)»|＂([^＂]*)＂|＇([^＇]*)＇/g, function(match) {
          return '<span style="color: #FF69B4; font-weight: bold;">' + match + '</span>';
        });
          contentDiv.innerHTML = formattedContent;

          // 强制重新渲染，确保橙色文字效果生效
          setTimeout(() => {
            contentDiv.style.display = 'none';
            contentDiv.offsetHeight; // 触发重新渲染
            contentDiv.style.display = '';
          }, 10);
        }
        window.placeholder1 = contentBeforePhone;

        // 解析<phone>后的内容，提取时间和日期
        if (contentAfterPhone) {
          // 查找<Status>标签，分别处理<Status>之前和之后的内容
          let phoneContent = contentAfterPhone;
          let statusContent = '';

          if (contentAfterPhone.includes('<Status>')) {
            const statusParts = contentAfterPhone.split('<Status>');
            phoneContent = statusParts[0].trim();
            statusContent = statusParts[1] ? statusParts[1].trim() : '';
          }

          // 解析时间|日期格式 (例如: 23:15|2024-11-15)
          if (phoneContent.includes('|')) {
            const [timeStr, dateStr] = phoneContent.split('|').map(s => s.trim());

            // 设置占位符2：时间
            if (timeStr) {
              document.querySelectorAll('.status-time, .time-large').forEach(el => {
                el.textContent = timeStr;
              });
              window.placeholder2 = timeStr;
              console.log('占位符2已设置为时间:', timeStr);
            }

            // 设置占位符3：日期
            if (dateStr) {
              document.querySelectorAll('.date-small').forEach(el => {
                el.textContent = dateStr;
              });
              window.placeholder3 = dateStr;
              console.log('占位符3已设置为日期:', dateStr);
            }
          } else {
            // 如果没有|分隔符，尝试直接解析单行内容
            const lines = phoneContent.split('\n').filter(line => line.trim());
            if (lines.length >= 1) {
              // 第一行作为时间
              const timeStr = lines[0].trim();
              document.querySelectorAll('.status-time, .time-large').forEach(el => {
                el.textContent = timeStr;
              });
              window.placeholder2 = timeStr;
              console.log('占位符2已设置为时间:', timeStr);
            }
            if (lines.length >= 2) {
              // 第二行作为日期
              const dateStr = lines[1].trim();
              document.querySelectorAll('.date-small').forEach(el => {
                el.textContent = dateStr;
              });
              window.placeholder3 = dateStr;
              console.log('占位符3已设置为日期:', dateStr);
            }
          }

          // 解析<Status>后的内容
          if (statusContent) {
            parseStatusContent(statusContent);
          }

          // 解析整个contentAfterPhone中的<twitter>内容
          if (contentAfterPhone && contentAfterPhone.includes('<twitter>')) {
            parseTwitterContent(contentAfterPhone);
          }

          // 解析整个contentAfterPhone中的<wechat>内容
          if (contentAfterPhone && contentAfterPhone.includes('<wechat>')) {
            parseWechatContent(contentAfterPhone);
          }

          // 解析整个contentAfterPhone中的<adv>内容
          if (contentAfterPhone && contentAfterPhone.includes('<adv>')) {
            parseAdvContent(contentAfterPhone);
          }

          // 解析整个contentAfterPhone中的<bilibili>内容
          if (contentAfterPhone && contentAfterPhone.includes('<bilibili>')) {
            parseBilibiliContent(contentAfterPhone);
          }

          // 解析整个contentAfterPhone中的<choice>内容
          if (contentAfterPhone && contentAfterPhone.includes('<choice>')) {
            parseChoiceContent(contentAfterPhone);
          } else {
            // 如果没有choice内容，隐藏选项界面
            hideOptionsInterface();
          }

          // 解析整个contentAfterPhone中的<peachhub>内容
          if (contentAfterPhone && contentAfterPhone.includes('<peachhub>')) {
            parsePeachhubContent(contentAfterPhone);
          }
        }

        console.log('已解析文段，占位符1已设置:', contentBeforePhone.substring(0, 100) + '...');
        return {
          placeholder1: contentBeforePhone,
          placeholder2: window.placeholder2 || '',
          placeholder3: window.placeholder3 || ''
        };
      } else if (rawContent && !rawContent.includes('<phone>')) {
        // 如果没有<phone>标签，则使用整个内容作为占位符1
        const contentDiv = document.querySelector('.letter-container .content');
        if (contentDiv) {
          // 将各种引号内的文字设置为粉红色，同时保持换行格式
          let formattedContent = rawContent.replace(/\n/g, '<br>');
          // 匹配所有类型的引号：英文双引号、中文双引号、英文单引号、中文单引号、书名号、全角引号等
          formattedContent = formattedContent.replace(/"([^"]*)"|"([^"]*)"|'([^']*)'|'([^']*)'|「([^」]*)」|『([^』]*)』|‚([^‚]*)‚|„([^„]*)„|‹([^‹]*)›|«([^«]*)»|＂([^＂]*)＂|＇([^＇]*)＇/g, function(match) {
            return '<span style="color: #FF69B4; font-weight: bold;">' + match + '</span>';
          });
          contentDiv.innerHTML = formattedContent;

          // 强制重新渲染，确保橙色文字效果生效
          setTimeout(() => {
            contentDiv.style.display = 'none';
            contentDiv.offsetHeight; // 触发重新渲染
            contentDiv.style.display = '';
          }, 10);
        }
        window.placeholder1 = rawContent;
        console.log('未找到<phone>标签，使用完整内容作为占位符1');
        return { placeholder1: rawContent };
      } else {
        console.log('未找到有效的文段内容，请在#rawContent元素中填入内容');
        return null;
      }
    }

    // 解析Status标签后的结构化内容
    function parseStatusContent(statusContent) {
      console.log('=== 开始解析Status内容 ===');
      console.log('原始statusContent:', statusContent);

      // 移除可能的</Status>结束标签
      let cleanContent = statusContent.replace(/<\/Status>/gi, '').trim();
      console.log('清理后的内容:', cleanContent);

      // 解析角色标签格式：<昕彤>数据<br>
      const characterData = {};

      // 查找所有角色标签
      const characterMatches = cleanContent.match(/<(昕彤|清韵|月绮|米尔可)>([^<]*?)(?:<br>|$)/g);
      console.log('角色匹配结果:', characterMatches);

      if (characterMatches) {
        characterMatches.forEach(match => {
          // 提取角色名和数据
          const characterMatch = match.match(/<(昕彤|清韵|月绮|米尔可)>([^<]*?)(?:<br>|$)/);
          if (characterMatch) {
            const characterName = characterMatch[1];
            const data = characterMatch[2].split('|').map(item => item.trim());
            characterData[characterName] = data;
            console.log(`解析到${characterName}的数据:`, data);
          }
        });
      } else {
        // 兼容旧格式：按<br>分割的行格式
        const lines = cleanContent.split('<br>').map(line => line.trim()).filter(line => line);
        if (lines.length >= 1) {
          characterData['昕彤'] = lines[0].split('|').map(item => item.trim());
        }
        if (lines.length >= 2) {
          characterData['清韵'] = lines[1].split('|').map(item => item.trim());
        }
        if (lines.length >= 3) {
          characterData['月绮'] = lines[2].split('|').map(item => item.trim());
        }
        if (lines.length >= 4) {
          characterData['米尔可'] = lines[3].split('|').map(item => item.trim());
        }
        console.log('使用兼容模式解析Status内容');
      }

      // 处理昕彤的数据 - 占位符4-12
      if (characterData['昕彤']) {
        const xintongData = characterData['昕彤'];
        for (let i = 0; i < xintongData.length && i <= 8; i++) {
          window[`placeholder${i + 4}`] = xintongData[i];

          if (i === 0) {
            // 性欲值，更新粉色进度条
            const sexualValue = parseInt(xintongData[i]) || 0;
            document.querySelectorAll('.progress-fill.pink').forEach(el => {
              el.style.width = `${sexualValue}%`;
            });
            document.querySelectorAll('.progress-value.pink').forEach(el => {
              el.textContent = `${sexualValue}%`;
            });
            console.log('占位符4已设置（昕彤性欲值）:', xintongData[i]);
          } else if (i === 1) {
            // 高潮值，更新紫色进度条
            const climaxValue = parseInt(xintongData[i]) || 0;
            document.querySelectorAll('.progress-fill.purple').forEach(el => {
              el.style.width = `${climaxValue}%`;
            });
            document.querySelectorAll('.progress-value.purple').forEach(el => {
