    // 解析Bilibili标签后的结构化内容
    function parseBilibiliContent(contentAfterPhone) {
      // 提取<bilibili>和</bilibili>之间的内容
      const bilibiliMatch = contentAfterPhone.match(/<bilibili>([\s\S]*?)<\/bilibili>/i);
      if (!bilibiliMatch) return;

      const bilibiliContent = bilibiliMatch[1].trim();

      // 按<br>分割成三部分
      const parts = bilibiliContent.split('<br>').map(part => part.trim());

      if (parts.length >= 1) {
        // 第一部分：观众数|排名|内容
        const popularityData = parts[0].split('|');
        if (popularityData.length >= 2) {
          const popularity = popularityData[0].trim();
          const rank = popularityData[1].trim();
          const content = popularityData.length >= 3 ? popularityData[2].trim() : '未开播';

          // 设置占位符52（人气和排名组合）
          window.placeholder52 = `${popularity}|${rank}`;

          // 更新bilibili界面的人气显示
          const popularityValue = document.querySelector('.popularity-value');
          if (popularityValue) {
            popularityValue.textContent = `当前人气：${popularity}`;
          }

          const popularityRank = document.querySelector('.popularity-rank');
          if (popularityRank) {
            popularityRank.textContent = `排名：第${rank}名`;
          }

          // 保存content到全局变量，供界面打开时使用
          window.bilibiliContent = content;

          // 根据内容字段设置直播图片
          updateBilibiliLiveImage(content);

          // 强制再次设置图片，确保生效
          setTimeout(() => {
            updateBilibiliLiveImage(content);
          }, 50);

          console.log('占位符52已设置（人气排名）:', `${popularity}|${rank}`);
          console.log('Bilibili内容字段:', content);
        }
      }

      if (parts.length >= 2) {
        // 第二部分：SC内容
        const scContent = parts[1].trim(); // 直接获取SC内容
        const scItems = scContent.split('|').map(item => item.trim()).filter(item => item);

        // 设置占位符53
        window.placeholder53 = scItems.join('|');

        // 更新bilibili界面的SC显示
        const scContainer = document.querySelector('.bilibili-sc');
        if (scContainer) {
          scContainer.innerHTML = '';

          // 先检查是否有用户输入的SC消息
          const userMessage = BilibiliStorage.getUserMessage();
          if (userMessage && !userMessage.isUsed && userMessage.message.includes('SC')) {
            // 添加用户SC消息（红色）
            const userScItem = document.createElement('div');
            userScItem.className = 'sc-item user-sc-item';
            userScItem.innerHTML = `
              <div class="sc-content">
                <div class="sc-text">${userMessage.message}</div>
              </div>
            `;
            scContainer.appendChild(userScItem);

            // 标记为已使用
            BilibiliStorage.markAsUsed();
          }

          // 添加原有的SC内容
          scItems.forEach((sc, index) => {
            const scItem = document.createElement('div');
            scItem.className = 'sc-item';
            scItem.innerHTML = `
              <div class="sc-content">
                <div class="sc-text">${sc}</div>
              </div>
            `;
            scContainer.appendChild(scItem);
          });
        }

        console.log('占位符53已设置（SC内容）:', window.placeholder53);
      }

      if (parts.length >= 3) {
        // 第三部分：弹幕内容
        const danmuContent = parts[2].trim();
        const danmuItems = danmuContent.split('|').map(item => item.trim()).filter(item => item);

        // 设置占位符54
        window.placeholder54 = danmuItems.join('|');

        // 更新bilibili界面的弹幕显示
        const chatContainer = document.querySelector('.bilibili-chat');
        if (chatContainer) {
          chatContainer.innerHTML = '';

          // 先检查是否有用户输入的弹幕消息（不包含SC的）
          const userMessage = BilibiliStorage.getUserMessage();
          if (userMessage && !userMessage.isUsed && !userMessage.message.includes('SC')) {
            // 添加用户弹幕消息（红色）
            const userChatMessage = document.createElement('div');
            userChatMessage.className = 'chat-message user-chat-message';
            userChatMessage.innerHTML = `
              <div class="chat-content">
                <div class="chat-text">${userMessage.message}</div>
              </div>
            `;
            chatContainer.appendChild(userChatMessage);

            // 标记为已使用
            BilibiliStorage.markAsUsed();
          }

          // 添加原有的弹幕内容
          danmuItems.forEach((danmu, index) => {
            const chatMessage = document.createElement('div');
            chatMessage.className = 'chat-message';
            chatMessage.innerHTML = `
              <div class="chat-content">
                <div class="chat-text">${danmu}</div>
              </div>
            `;
            chatContainer.appendChild(chatMessage);
