    // 微信消息本地存储管理
    const WechatStorage = {
      key: 'wechatMessageGroups',
      maxGroups: 5,

      // 获取所有消息群
      getMessageGroups: function() {
        const stored = localStorage.getItem(this.key);
        return stored ? JSON.parse(stored) : [];
      },

      // 保存消息群
      saveMessageGroups: function(groups) {
        // 只保留最近5次消息群
        const limitedGroups = groups.slice(-this.maxGroups);
        localStorage.setItem(this.key, JSON.stringify(limitedGroups));
      },

      // 添加新消息群
      addMessageGroup: function(groupData) {
        const groups = this.getMessageGroups();
        groups.push({
          id: Date.now(),
          timestamp: new Date().toISOString(),
          messages: groupData.messages || [],
          userMessages: [] // 用户发送的消息
        });
        this.saveMessageGroups(groups);
      },

      // 添加用户消息到最新群
      addUserMessage: function(message) {
        const groups = this.getMessageGroups();
        if (groups.length > 0) {
          groups[groups.length - 1].userMessages.push({
            content: message,
            timestamp: new Date().toISOString()
          });
          this.saveMessageGroups(groups);
        }
      },

      // 获取最新消息群
      getLatestGroup: function() {
        const groups = this.getMessageGroups();
        return groups.length > 0 ? groups[groups.length - 1] : null;
      }
    };

    // PeachHub视频本地存储管理
    const PeachhubStorage = {
      key: 'peachhubVideos',
      maxVideos: 50,

      // 获取所有视频
      getAllVideos: function() {
        const stored = localStorage.getItem(this.key);
        return stored ? JSON.parse(stored) : [];
      },

      // 保存视频列表
      saveVideos: function(videos) {
        // 只保留最近50个视频
        const limitedVideos = videos.slice(-this.maxVideos);
        localStorage.setItem(this.key, JSON.stringify(limitedVideos));
      },

      // 添加新视频
      addVideo: function(videoData) {
        const videos = this.getAllVideos();
        const newVideo = {
          id: Date.now(),
          timestamp: new Date().toISOString(),
          title: videoData.title || '未命名视频',
          playCount: videoData.playCount || '1000',
          likeRate: videoData.likeRate || '95%',
          videoThumbnail: videoData.videoThumbnail || '',
          time: videoData.time || '',
          description: videoData.description || '',
          tags: videoData.tags || [],
          comments: videoData.comments || [],
          source: 'peachhub' // 标记来源
        };

        // 检查是否已存在相同标题的视频
        const existingIndex = videos.findIndex(video => video.title === newVideo.title);
        if (existingIndex >= 0) {
          // 如果存在，更新现有视频
          videos[existingIndex] = newVideo;
          console.log('更新已存在的PeachHub视频:', newVideo.title);
        } else {
          // 如果不存在，添加新视频
          videos.push(newVideo);
          console.log('添加新的PeachHub视频:', newVideo.title);
        }

        this.saveVideos(videos);
        return newVideo;
      },

      // 根据ID获取视频
      getVideoById: function(id) {
        const videos = this.getAllVideos();
        return videos.find(video => video.id == id);
      },

      // 根据标题搜索视频
      searchByTitle: function(title) {
        const videos = this.getAllVideos();
        return videos.filter(video => 
          video.title.toLowerCase().includes(title.toLowerCase())
        );
      },

      // 根据标签搜索视频
      searchByTag: function(tag) {
        const videos = this.getAllVideos();
        return videos.filter(video => 
          video.tags && video.tags.some(videoTag => 
            videoTag.toLowerCase().includes(tag.toLowerCase())
          )
        );
      },

      // 删除视频
      removeVideo: function(id) {
        const videos = this.getAllVideos();
        const filteredVideos = videos.filter(video => video.id != id);
        this.saveVideos(filteredVideos);
      },

      // 清除所有视频
      clearAllVideos: function() {
        localStorage.removeItem(this.key);
      },

      // 获取视频统计信息
      getStats: function() {
        const videos = this.getAllVideos();
        return {
          totalVideos: videos.length,
          totalTags: [...new Set(videos.flatMap(video => video.tags || []))].length,
          averageLikes: videos.length > 0 
            ? Math.round(videos.reduce((sum, video) => {
                const likeRate = parseInt(video.likeRate) || 0;
                return sum + likeRate;
              }, 0) / videos.length)
            : 0
        };
      }
    };

