        <div style="font-size: 0.9rem; color: #999; margin-top: 5px;">
          找到 ${results.length} 个视频
        </div>
      `;
      videoGrid.appendChild(searchHeader);

      if (results.length === 0) {
        const emptyResult = document.createElement('div');
        emptyResult.style.cssText = `
          text-align: center;
          padding: 40px;
          color: #666;
