    // 更新PeachHub界面内容
    function updatePeachhubInterface(peachhubData) {
      console.log('=== 更新PeachHub界面 ===');
      console.log('接收到的数据:', peachhubData);

      if (!peachhubData) return;

      // 更新视频标题
      if (peachhubData.title) {
        const videoTitles = document.querySelectorAll('.video-title');
        videoTitles.forEach(title => {
          title.textContent = peachhubData.title;
        });

        // 更新详情页面的标题
        const textTitle = document.querySelector('.text-title');
        if (textTitle) {
          textTitle.textContent = peachhubData.title + ' - 视频介绍';
        }
      }

      // 更新播放量和好评率
      if (peachhubData.playCount && peachhubData.likeRate) {
        const viewsElements = document.querySelectorAll('.views');
        const likesElements = document.querySelectorAll('.likes');

        viewsElements.forEach(views => {
          views.innerHTML = `👁️ ${peachhubData.playCount}`;
        });

        likesElements.forEach(likes => {
          likes.innerHTML = `❤️ ${peachhubData.likeRate}`;
        });

        // 更新详情页面的统计数据
        const videoViews = document.querySelector('.video-views span');
        const videoLikes = document.querySelector('.video-likes span');
        if (videoViews) videoViews.textContent = `👁️ ${peachhubData.playCount} 播放`;
        if (videoLikes) videoLikes.textContent = `❤️ ${peachhubData.likeRate} 推荐`;
      }

      // 更新视频描述
      if (peachhubData.description) {
        const textBody = document.querySelector('.text-body');
        if (textBody) {
          textBody.textContent = peachhubData.description;
        }
      }

      // 更新标签
      if (peachhubData.tags && peachhubData.tags.length > 0) {
        const tagsContainer = document.querySelector('.tags-container');
        if (tagsContainer) {
          tagsContainer.innerHTML = '';
          peachhubData.tags.forEach(tag => {
            const tagElement = document.createElement('div');
            tagElement.className = 'tag-item';
            tagElement.textContent = tag;

            // 添加标签点击事件
            tagElement.addEventListener('click', function(e) {
              e.stopPropagation();
              showTagSearchResults(tag);
            });

            tagsContainer.appendChild(tagElement);
          });
        }
      }

      // 更新评论 (不包含用户名和时间)
      if (peachhubData.comments && peachhubData.comments.length > 0) {
        const commentsTitle = document.querySelector('.comments-title');
        if (commentsTitle) {
          commentsTitle.textContent = `评论 (${peachhubData.comments.length})`;
        }

        // 查找评论容器的父元素
        const videoComments = document.querySelector('.video-comments');
        if (videoComments) {
          // 清除现有的评论项，但保留标题
          const existingComments = videoComments.querySelectorAll('.comment-item');
          existingComments.forEach(comment => comment.remove());

          // 添加新的评论
          peachhubData.comments.forEach((comment, index) => {
            const commentItem = document.createElement('div');
            commentItem.className = 'comment-item';
            commentItem.innerHTML = `
              <div class="comment-text">${comment}</div>
            `;
            videoComments.appendChild(commentItem);
          });
        }
      }

      console.log('PeachHub界面更新完成');
    }

