    // 格式化视频时长
    function formatDuration(timeStr) {
      if (!timeStr) return '🍑';

      // 如果时间字符串包含冒号，认为是时分秒格式
      if (timeStr.includes(':')) {
        return timeStr.split(' ')[0]; // 取时间部分
      }

      // 否则返回桃子图标
      return '🍑';
    }

