    // 根据分类显示视频
    function displayVideosByCategory(categoryName) {
      const videos = PeachhubStorage.getAllVideos();
      let displayVideos = [];

      switch(categoryName) {
        case '最新':
          // 按时间倒序排列，最新的在前
          displayVideos = videos.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));
          break;

        case '热门':
          // 按播放量排序（假设播放量是数字加"万"或"千"）
          displayVideos = videos.sort((a, b) => {
            const aViews = parseViewCount(a.playCount);
            const bViews = parseViewCount(b.playCount);
            return bViews - aViews;
          });
          break;

        case '收藏':
          // 按好评率排序
          displayVideos = videos.sort((a, b) => {
            const aRate = parseInt(a.likeRate) || 0;
            const bRate = parseInt(b.likeRate) || 0;
            return bRate - aRate;
          });
          break;

        default:
          displayVideos = videos;
      }

      // 更新视频网格
      updateVideoGrid(displayVideos, categoryName);
    }

    // 解析播放量数字（支持"万"、"千"等单位）
    function parseViewCount(viewCountStr) {
      if (!viewCountStr) return 0;

      const numStr = viewCountStr.replace(/[^0-9.万千]/g, '');
      let num = parseFloat(numStr) || 0;

      if (viewCountStr.includes('万')) {
        num *= 10000;
      } else if (viewCountStr.includes('千')) {
        num *= 1000;
      }

      return num;
    }

