    function initializeBaikeEvents() {
      // 为主分类添加点击事件
      const mainCategories = document.querySelectorAll('.baike-main-categories .main-category');
      mainCategories.forEach(category => {
        category.addEventListener('click', function(e) {
          e.stopPropagation();

          // 移除其他主分类的选中状态
          mainCategories.forEach(cat => cat.classList.remove('active'));
          // 选中当前分类
          this.classList.add('active');

          const categoryKey = this.getAttribute('data-category');
          const categoryInfo = baikeDatabase[categoryKey];

          // 隐藏所有子分类容器
          if (baikeSubcategories) {
            baikeSubcategories.style.display = 'none';
          }
          if (baikeSchoolSubcategories) {
            baikeSchoolSubcategories.style.display = 'none';
          }

          // 根据分类显示对应的子分类
          if (categoryKey === 'family') {
            if (baikeSubcategories) {
              baikeSubcategories.style.display = 'grid';
            }
          } else if (categoryKey === 'school') {
            if (baikeSchoolSubcategories) {
              baikeSchoolSubcategories.style.display = 'flex';
            }
          }

          // 显示主分类信息
          if (categoryInfo) {
            baikeResultTitle.textContent = categoryInfo.title;
            baikeResultContent.textContent = categoryInfo.content;
            baikeResult.classList.add('show');
          }

          // 发送分类请求
          sendBaikeRequest(`切换到分类：${categoryInfo.title}`);
        });
      });

      // 为家庭子分类添加点击事件
      const familySubcategories = document.querySelectorAll('.baike-subcategories .baike-category');
      familySubcategories.forEach(category => {
        category.addEventListener('click', function(e) {
          e.stopPropagation();

          // 移除其他子分类的选中状态
          familySubcategories.forEach(cat => cat.classList.remove('selected'));
          // 选中当前分类
          this.classList.add('selected');

          // 显示分类信息
