    const BilibiliStorage = {
      key: 'bilibiliUserMessages',

      // 保存用户消息
      saveUserMessage: function(message) {
        localStorage.setItem(this.key, JSON.stringify({
          message: message,
          timestamp: Date.now(),
          isUsed: false // 标记是否已使用
        }));
      },

      // 获取用户消息
      getUserMessage: function() {
        const stored = localStorage.getItem(this.key);
        return stored ? JSON.parse(stored) : null;
      },

      // 标记消息为已使用
      markAsUsed: function() {
        const stored = this.getUserMessage();
        if (stored) {
          stored.isUsed = true;
          localStorage.setItem(this.key, JSON.stringify(stored));
        }
      },

      // 清除已使用的消息
      clearUsedMessage: function() {
        const stored = this.getUserMessage();
        if (stored && stored.isUsed) {
          localStorage.removeItem(this.key);
        }
      }
    };

