    // 处理bilibili数据的函数
    function processBilibiliData(bilibiliData, scData, danmuData) {
        if (!bilibiliData) return;

        // 分割第一行数据（人气和排名）
        const [popularity, rank] = bilibiliData.split('|');

        // 更新人气显示
        const popularityValue = document.querySelector('.popularity-value');
        if (popularityValue) {
            popularityValue.textContent = `当前人气：${popularity}`;
        }

        // 更新排名显示
        const popularityRank = document.querySelector('.popularity-rank');
        if (popularityRank) {
            popularityRank.textContent = `排名：${rank}`;
        }

        // 处理SC数据
        if (scData) {
            const scContainer = document.querySelector('.bilibili-sc');
            if (scContainer) {
                // 清空现有SC
                scContainer.innerHTML = '';

                // 分割SC数据
                const scItems = scData.split('|');

                // 为每个SC创建新的元素
                scItems.forEach((sc) => {
                    if (sc.trim()) {  // 只处理非空的SC
                        const scItem = document.createElement('div');
                        scItem.className = 'sc-item';
                        scItem.innerHTML = `
                            <div class="sc-content">
                                <div class="sc-text">${sc}</div>
                            </div>
                        `;
                        scContainer.appendChild(scItem);
                    }
                });
            }
        }

        // 处理弹幕数据
        if (danmuData) {
            const chatContainer = document.querySelector('.bilibili-chat');
            if (chatContainer) {
                // 清空现有弹幕
                chatContainer.innerHTML = '';

                // 去除最后一个换行符并分割弹幕数据
                const cleanDanmuData = danmuData.trim();
                const danmuItems = cleanDanmuData.split('|').map(item => item.trim());

                // 为每个弹幕创建新的元素
                danmuItems.forEach((danmu) => {
                    if (danmu) {  // 只处理非空的弹幕
                        const chatMessage = document.createElement('div');
                        chatMessage.className = 'chat-message';
                        chatMessage.innerHTML = `
                            <div class="chat-content">
                                <div class="chat-text">${danmu}</div>
                            </div>
                        `;
                        chatContainer.appendChild(chatMessage);
                    }
                });
            }
        }
    }

