        // 5. 初始化选项APP状态（显示choice提示信息）
        // 延迟检查choice数据，如果没有则显示提示信息
        setTimeout(() => {
          const optionsContent = document.querySelector('.options-content');
          if (optionsContent && optionsContent.style.display !== 'flex') {
            hideOptionsInterface();
            console.log('初始化：没有检测到choice数据，显示提示信息');
          }
        }, 200);

        // 6. 先解析bilibili数据，再设置默认图片
        // bilibili数据会通过parseContentAndSetPlaceholder自动解析

        // 7. 如果没有bilibili内容，则设置默认图片为"未开播"
        setTimeout(() => {
          if (!window.bilibiliContent) {
            updateBilibiliLiveImage('未开播');
          }
        }, 100);

        // 8. 初始化催眠APP头像同步
        setTimeout(() => {
          syncHypnosisAvatars();
        }, 300);
    });

    // 初始化头像显示状态
    function initializeAvatarVisibility() {
      const avatars = ['avatarA', 'avatarB', 'avatarC', 'avatarD'];
      avatars.forEach(avatarId => {
        const avatar = document.getElementById(avatarId);
        if (avatar) {
          avatar.style.display = 'none';
        }
      });

      // 同时隐藏催眠APP的头像
      const hypnosisAvatars = ['hypnosisAvatarA', 'hypnosisAvatarB', 'hypnosisAvatarC', 'hypnosisAvatarD'];
      hypnosisAvatars.forEach(avatarId => {
        const avatar = document.getElementById(avatarId);
        if (avatar) {
          avatar.style.display = 'none';
        }
      });

      // 隐藏头像容器
      const avatarContainer = document.querySelector('.avatar-container');
      if (avatarContainer) {
        avatarContainer.style.display = 'none';
      }

      console.log('初始化：隐藏所有头像（包括催眠APP头像）');
    }


window.updateContent(`
