    // 解析WeChat标签后的结构化内容
    function parseWechatContent(contentAfterPhone) {
      // 提取<wechat>和</wechat>之间的内容
      const wechatMatch = contentAfterPhone.match(/<wechat>([\s\S]*?)<\/wechat>/i);
      if (!wechatMatch) return;

      let wechatContent = wechatMatch[1].trim();

      // 解析消息和时间
      const items = [];

      // 定义角色信息
      const characters = {
        '昕彤': {
          name: '昕彤大人(^_^)d',
          avatar: 'https://files.catbox.moe/98otq8.png'
        },
        '月绮': {
          name: 'AAA月绮忏悔',
          avatar: 'https://files.catbox.moe/ypnli6.png'
        },
        '清韵': {
          name: '是清韵哦',
          avatar: 'https://files.catbox.moe/ajghy0.jpeg'
        },
        '米尔可': {
          name: '米尔可',
          avatar: 'https://files.catbox.moe/p7m5t5.png'
        }
      };

      // 按标签分割内容，包括时间和角色
      const parts = wechatContent.split(/(<[^>]+>)/);
      let currentCharacter = null;

      for (let i = 0; i < parts.length; i++) {
        const part = parts[i].trim();
        if (!part) continue;

        // 检查是否是时间标签
        const timeMatch = part.match(/^<time>$/);
        if (timeMatch && i + 2 < parts.length) {
          const timeContent = parts[i + 2].trim();
          if (timeContent) {
            items.push({
              type: 'time',
              content: timeContent
            });
          }
          i += 2; // 跳过时间内容和结束标签
          continue;
        }

        // 检查是否是角色标签
        const characterMatch = part.match(/^<(昕彤|月绮|清韵|米尔可)>$/);
        if (characterMatch) {
          currentCharacter = characterMatch[1];
        } else if (currentCharacter && characters[currentCharacter]) {
          // 移除可能的结束标签
          const cleanMessage = part.replace(/<\/[^>]+>/g, '').trim();
          if (cleanMessage) {
            items.push({
              type: 'message',
              character: currentCharacter,
              name: characters[currentCharacter].name,
              avatar: characters[currentCharacter].avatar,
              content: cleanMessage
            });
          }
        }
      }

      // 生成微信界面内容
      generateWechatContent(items);

      // 设置占位符47（保持兼容性）
      window.placeholder47 = wechatContent;

      console.log('微信内容解析完成，共解析', items.length, '个项目');
    }

    // 生成微信内容界面（包含消息和时间）
    function generateWechatContent(items) {
      const wechatContent = document.getElementById('wechatContent');
      if (!wechatContent || !items.length) return;

      // 清空现有内容
      wechatContent.innerHTML = '';

      items.forEach(item => {
        if (item.type === 'time') {
          // 生成时间气泡
          const timeDiv = document.createElement('div');
          timeDiv.className = 'time-container';
          timeDiv.innerHTML = `<span class="time-bubble">${item.content}</span>`;
          wechatContent.appendChild(timeDiv);
        } else if (item.type === 'message') {
          // 生成消息气泡
          const messageDiv = document.createElement('div');
          messageDiv.className = 'wechat-message';

          messageDiv.innerHTML = `
            <div class="wechat-avatar" style="background-image: url('${item.avatar}')"></div>
            <div class="wechat-message-content">
              <div class="wechat-username">${item.name}</div>
              <div class="wechat-bubble">
                <div class="wechat-message-text">${item.content}</div>
              </div>
            </div>
          `;

          wechatContent.appendChild(messageDiv);
        }
      });

      // 保存到本地存储
      WechatStorage.addMessageGroup({ messages: items });

      // 加载并显示用户之前发送的消息
      loadUserMessages();

      // 滚动到顶部（最新消息）
      setTimeout(() => {
        wechatContent.scrollTop = 0;
      }, 100);

      console.log('微信界面已生成，包含', items.length, '个项目');
    }

    // 加载用户之前发送的消息
    function loadUserMessages() {
      const latestGroup = WechatStorage.getLatestGroup();
      if (!latestGroup || !latestGroup.userMessages.length) return;

      const wechatContent = document.getElementById('wechatContent');
      if (!wechatContent) return;

      // 添加用户之前发送的消息
      latestGroup.userMessages.forEach(userMsg => {
        const messageDiv = document.createElement('div');
        messageDiv.className = 'wechat-message sent';

        messageDiv.innerHTML = `
          <div class="wechat-bubble">
            <div class="wechat-message-text">${userMsg.content}</div>
          </div>
        `;

        wechatContent.appendChild(messageDiv);
      });
    }

