      const topButtons = ['常识修改', '催眠', '集体洗脑'];
      const bottomButtons = ['高潮', '发情', '排卵'];

      // 获取选中的上下组按钮
      const selectedTopButtons = selectedButtons.filter(btn => topButtons.includes(btn));
      const selectedBottomButtons = selectedButtons.filter(btn => bottomButtons.includes(btn));

      try {
        // 收集所有请求
        const requests = [];

        // 处理上面组的按钮
        if (selectedTopButtons.length > 0) {
          // 如果有选中的自定义角色
          const customCharacters = Array.from(document.querySelectorAll('.custom-name-tag.active'))
            .map(tag => tag.getAttribute('data-name'));

          // 对每个自定义角色添加请求
          if (customCharacters.length > 0) {
            for (const character of customCharacters) {
              for (const button of selectedTopButtons) {
                if (button === '催眠') {
                  requests.push(`催眠${character}`);
                } else if (button === '常识修改') {
                  requests.push(`对${character}进行常识修改`);
                } else {
                  requests.push(`对${character}进行${button}`);
                }
              }
            }
          }

          // 处理对周围人群的请求
          const crowdRequests = [];
          for (const button of selectedTopButtons) {
            if (button === '催眠') {
              // 如果有自定义角色被催眠，或者没有自定义角色，则催眠周围人群
              if (customCharacters.length > 0 || selectedTopButtons.includes('催眠')) {
                crowdRequests.push('对周围的人群进行催眠');
              }
            } else if (button === '常识修改') {
              // 常识修改总是对周围人群生效
              crowdRequests.push('对周围的人群进行常识修改');
            } else {
              crowdRequests.push(`对周围的人群进行${button}`);
            }
          }
          requests.push(...crowdRequests);
        }

        // 处理下面组的按钮
        if (selectedBottomButtons.length > 0) {
          const targetCharacters = selectedCharacters.length > 0 
            ? selectedCharacters.join('、')
            : '月绮、昕彤、清韵、米尔可';
          requests.push(`对${targetCharacters}进行强制${selectedBottomButtons.join('和强制')}`);
