      bilibiliInput.addEventListener('keypress', function(e) {
        if (e.key === 'Enter' && this.value.trim()) {
          sendBilibiliMessage();
        }
      });

      // 点击发送按钮
      bilibiliSend.addEventListener('click', function(e) {
        e.stopPropagation();
        sendBilibiliMessage();
      });
    }

    // 发送Bilibili消息的函数
    async function sendBilibiliMessage() {
      const message = bilibiliInput.value.trim();
      if (!message) return;

      try {
        // 保存用户消息到本地存储
        BilibiliStorage.saveUserMessage(message);

        const triggerRequest = `/trigger <Request: {{user}}使用bilibili发送：${message}>`;
        const sendRequest = `/send <Request: {{user}}使用bilibili发送：${message}>`;

        // 如果triggerSlash函数可用，使用它；否则输出到控制台
        if (typeof triggerSlash === 'function') {
          await triggerSlash(sendRequest);
          await triggerSlash(triggerRequest);
        } else {
          console.log('Bilibili消息发送 send:', sendRequest);
          console.log('Bilibili消息发送 trigger:', triggerRequest);
        }

        // 清空输入框
        bilibiliInput.value = '';
      } catch (error) {
        console.error('发送Bilibili消息时出错:', error);
      }
    }

    // 添加SC区域滚动控制
    const scContainer = document.querySelector('.bilibili-sc');
    if (scContainer) {
      scContainer.addEventListener('wheel', function(e) {
        e.preventDefault();
        // 获取当前滚动位置
        const currentScroll = this.scrollLeft;
        // 根据滚轮方向调整滚动位置
        // deltaY > 0 表示向下滚动，对应向右移动
        // deltaY < 0 表示向上滚动，对应向左移动
        const scrollAmount = e.deltaY > 0 ? 100 : -100;
        this.scrollLeft = currentScroll + scrollAmount;
      });
    }



    // 处理bilibili数据的函数
    function processBilibiliData(bilibiliData, scData, danmuData) {
        if (!bilibiliData) return;

        // 分割第一行数据（人气和排名）
        const [popularity, rank] = bilibiliData.split('|');

        // 更新人气显示
        const popularityValue = document.querySelector('.popularity-value');
        if (popularityValue) {
            popularityValue.textContent = `当前人气：${popularity}`;
        }

        // 更新排名显示
        const popularityRank = document.querySelector('.popularity-rank');
        if (popularityRank) {
            popularityRank.textContent = `排名：${rank}`;
        }

        // 处理SC数据
        if (scData) {
            const scContainer = document.querySelector('.bilibili-sc');
            if (scContainer) {
                // 清空现有SC
                scContainer.innerHTML = '';

                // 分割SC数据
                const scItems = scData.split('|');

                // 为每个SC创建新的元素
                scItems.forEach((sc) => {
                    if (sc.trim()) {  // 只处理非空的SC
                        const scItem = document.createElement('div');
                        scItem.className = 'sc-item';
                        scItem.innerHTML = `
                            <div class="sc-content">
                                <div class="sc-text">${sc}</div>
                            </div>
                        `;
                        scContainer.appendChild(scItem);
                    }
                });
            }
        }

        // 处理弹幕数据
        if (danmuData) {
            const chatContainer = document.querySelector('.bilibili-chat');
            if (chatContainer) {
                // 清空现有弹幕
                chatContainer.innerHTML = '';

                // 去除最后一个换行符并分割弹幕数据
                const cleanDanmuData = danmuData.trim();
                const danmuItems = cleanDanmuData.split('|').map(item => item.trim());

                // 为每个弹幕创建新的元素
                danmuItems.forEach((danmu) => {
                    if (danmu) {  // 只处理非空的弹幕
                        const chatMessage = document.createElement('div');
                        chatMessage.className = 'chat-message';
                        chatMessage.innerHTML = `
                            <div class="chat-content">
                                <div class="chat-text">${danmu}</div>
                            </div>
                        `;
                        chatContainer.appendChild(chatMessage);
                    }
                });
            }
        }
    }

    // 在页面加载时初始化所有数据
    document.addEventListener('DOMContentLoaded', () => {
        // 1. 首先解析文段并设置占位符1
        parseContentAndSetPlaceholder();

        // 2. 设置随机头像
        setRandomAvatars();



        // 4. 初始化头像显示状态（默认隐藏所有头像）
        initializeAvatarVisibility();

        // 5. 初始化选项APP状态（显示choice提示信息）
        // 延迟检查choice数据，如果没有则显示提示信息
        setTimeout(() => {
          const optionsContent = document.querySelector('.options-content');
          if (optionsContent && optionsContent.style.display !== 'flex') {
            hideOptionsInterface();
            console.log('初始化：没有检测到choice数据，显示提示信息');
          }
        }, 200);

        // 6. 先解析bilibili数据，再设置默认图片
        // bilibili数据会通过parseContentAndSetPlaceholder自动解析

        // 7. 如果没有bilibili内容，则设置默认图片为"未开播"
        setTimeout(() => {
          if (!window.bilibiliContent) {
            updateBilibiliLiveImage('未开播');
          }
        }, 100);

        // 8. 初始化催眠APP头像同步
        setTimeout(() => {
          syncHypnosisAvatars();
        }, 300);
    });

    // 初始化头像显示状态
    function initializeAvatarVisibility() {
      const avatars = ['avatarA', 'avatarB', 'avatarC', 'avatarD'];
      avatars.forEach(avatarId => {
        const avatar = document.getElementById(avatarId);
        if (avatar) {
          avatar.style.display = 'none';
        }
      });

      // 同时隐藏催眠APP的头像
      const hypnosisAvatars = ['hypnosisAvatarA', 'hypnosisAvatarB', 'hypnosisAvatarC', 'hypnosisAvatarD'];
      hypnosisAvatars.forEach(avatarId => {
        const avatar = document.getElementById(avatarId);
        if (avatar) {
          avatar.style.display = 'none';
        }
      });

      // 隐藏头像容器
      const avatarContainer = document.querySelector('.avatar-container');
      if (avatarContainer) {
        avatarContainer.style.display = 'none';
      }

      console.log('初始化：隐藏所有头像（包括催眠APP头像）');
    }


window.updateContent(`
