           resize: vertical;
           min-height: 60px;
         }

         .upload-actions {
           margin-bottom: 20px;
         }

         .upload-btn {
           width: 100%;
           padding: 12px 20px;
           background: linear-gradient(135deg, #ffacae, #ffc0cb);
           border: none;
           border-radius: 12px;
           color: white;
           font-size: 1rem;
           font-weight: bold;
           cursor: pointer;
           display: flex;
           align-items: center;
           justify-content: center;
           gap: 8px;
           transition: all 0.3s ease;
           box-shadow: 0 4px 12px rgba(255, 172, 174, 0.3);
         }

         .upload-btn:hover {
           transform: translateY(-2px);
           box-shadow: 0 6px 16px rgba(255, 172, 174, 0.4);
         }

         .upload-btn:active {
           transform: translateY(0);
           box-shadow: 0 2px 8px rgba(255, 172, 174, 0.3);
         }

         .upload-btn:disabled {
           background: #ccc;
           cursor: not-allowed;
           transform: none;
           box-shadow: none;
         }

         .btn-icon {
           font-size: 1.1rem;
         }

         .upload-progress {
           margin-top: 15px;
         }

         .progress-bar {
           width: 100%;
           height: 8px;
           background: #f0f0f0;
           border-radius: 4px;
           overflow: hidden;
           margin-bottom: 8px;
         }

         .progress-fill {
           height: 100%;
           background: linear-gradient(90deg, #ffacae, #ffc0cb);
           border-radius: 4px;
           transition: width 0.3s ease;
           width: 0%;
