    // 解析Twitter标签后的结构化内容
    function parseTwitterContent(contentAfterPhone) {
      // 提取<twitter>和</twitter>之间的内容
      const twitterMatch = contentAfterPhone.match(/<twitter>([\s\S]*?)<\/twitter>/i);
      if (!twitterMatch) return;

      const twitterContent = twitterMatch[1].trim();

      // 解析所有account，支持account1到account10
      const accountMatches = twitterContent.match(/<account\d+>([\s\S]*?)<\/account\d+>/gi);

      let currentPlaceholderIndex = 31;
      const allTweets = [];

      // 兼容模式：如果没有找到account标签，将整个内容作为account1处理
      if (!accountMatches) {
        console.log('Twitter兼容模式：未找到account标签，将整个内容作为account1处理');

        const lines = twitterContent.split('<br>').map(line => line.trim()).filter(line => line);

        if (lines.length > 0) {
          // 解析主推文（第一行）
          const mainTweetData = lines[0].split('|').map(item => item.trim());
          if (mainTweetData.length >= 7) {
            // 存储主推文数据到对应占位符
            for (let i = 0; i < 7; i++) {
              window[`placeholder${currentPlaceholderIndex + i}`] = mainTweetData[i];
              console.log(`占位符${currentPlaceholderIndex + i}已设置（Twitter 兼容模式）:`, mainTweetData[i]);
            }

            // 解析回复（从第二行开始）
            const replies = [];
            for (let i = 1; i < lines.length; i++) {
              const replyData = lines[i].split('|').map(item => item.trim());
              if (replyData.length >= 3) {
                replies.push({
                  username: replyData[0],
                  handle: replyData[1],
                  content: replyData[2]
                });
              }
            }

            // 存储到allTweets数组
            allTweets.push({
              username: mainTweetData[0],
              handle: mainTweetData[1],
              followers: mainTweetData[2],
              content: mainTweetData[3],
              retweets: mainTweetData[4],
              comments: mainTweetData[5],
              likes: mainTweetData[6],
              replies: replies
            });
          }
        }
      } else {
        // 标准模式：处理account标签
        accountMatches.forEach((accountMatch, accountIndex) => {
          // 如果已经处理了10个账号，就停止
          if (accountIndex >= 10) return;

          // 提取account内容
          const accountContent = accountMatch.replace(/<\/?account\d+>/gi, '').trim();
          const lines = accountContent.split('<br>').map(line => line.trim()).filter(line => line);

          if (lines.length === 0) return;

          // 解析主推文（第一行）
          const mainTweetData = lines[0].split('|').map(item => item.trim());
          if (mainTweetData.length >= 7) {
            // 存储主推文数据到对应占位符
            for (let i = 0; i < 7; i++) {
              window[`placeholder${currentPlaceholderIndex + i}`] = mainTweetData[i];
              console.log(`占位符${currentPlaceholderIndex + i}已设置（Twitter ${accountIndex + 1}）:`, mainTweetData[i]);
            }

            // 解析回复（从第二行开始）
            const replies = [];
            for (let i = 1; i < lines.length; i++) {
              const replyData = lines[i].split('|').map(item => item.trim());
              if (replyData.length >= 3) {
                replies.push({
                  username: replyData[0],
                  handle: replyData[1],
                  content: replyData[2]
                });
              }
            }

            // 存储到allTweets数组
            allTweets.push({
              username: mainTweetData[0],
              handle: mainTweetData[1],
              followers: mainTweetData[2],
              content: mainTweetData[3],
              retweets: mainTweetData[4],
              comments: mainTweetData[5],
              likes: mainTweetData[6],
              replies: replies
            });

            // 更新占位符索引，为下一个账号准备
            currentPlaceholderIndex += 7;
          }
        });
      }

      // 存储解析的Twitter数据供界面使用
      window.twitterData = allTweets;

      // 动态生成Twitter界面内容
      generateTwitterInterface(allTweets);

      console.log('Twitter内容解析完成，共解析', allTweets.length, '个账号');
    }

