    // 解析PeachHub标签后的结构化内容
    function parsePeachhubContent(contentAfterPhone) {
      console.log('=== 开始解析PeachHub内容 ===');

      // 提取<peachhub>和</peachhub>之间的内容
      const peachhubMatch = contentAfterPhone.match(/<peachhub>([\s\S]*?)<\/peachhub>/i);
      if (!peachhubMatch) return;

      const peachhubContent = peachhubMatch[1].trim();
      console.log('PeachHub原始内容:', peachhubContent);

      // 解析各个标签
      const peachhubData = {};

      // 解析标题
      const titleMatch = peachhubContent.match(/<title>(.*?)<\/title>/i);
      if (titleMatch) {
        peachhubData.title = titleMatch[1].trim();
        console.log('解析到标题:', peachhubData.title);
      }

      // 解析参数 (播放量|好评率|视频封面|时间)
      const parameterMatch = peachhubContent.match(/<parameter>(.*?)<\/parameter>/i);
      if (parameterMatch) {
        const parameters = parameterMatch[1].split('|').map(p => p.trim());
        if (parameters.length >= 3) {
          peachhubData.playCount = parameters[0];
          peachhubData.likeRate = parameters[1];
          peachhubData.videoThumbnail = parameters[2];
          // 如果有时间参数，使用它；否则使用占位符2和3
          if (parameters.length >= 4) {
            peachhubData.time = parameters[3];
          } else {
            peachhubData.time = `${window.placeholder2 || ''} ${window.placeholder3 || ''}`.trim();
          }
        }
        console.log('解析到参数:', parameters);
      }

      // 解析描述
      const descriptionMatch = peachhubContent.match(/<description>(.*?)<\/description>/i);
      if (descriptionMatch) {
        peachhubData.description = descriptionMatch[1].trim();
        console.log('解析到描述:', peachhubData.description);
      }

      // 解析标签
      const tagsMatch = peachhubContent.match(/<tags>(.*?)<\/tags>/i);
      if (tagsMatch) {
        peachhubData.tags = tagsMatch[1].split('|').map(tag => tag.trim()).filter(tag => tag);
        console.log('解析到标签:', peachhubData.tags);
      }

      // 解析评论 (不包含用户名和时间)
      const commentMatch = peachhubContent.match(/<comment>(.*?)<\/comment>/i);
      if (commentMatch) {
        peachhubData.comments = commentMatch[1].split('|').map(comment => comment.trim()).filter(comment => comment);
        console.log('解析到评论:', peachhubData.comments);
      }

      // 存储解析的数据供PeachHub界面使用
      window.peachhubData = peachhubData;

      // 更新PeachHub界面内容
      updatePeachhubInterface(peachhubData);

      // 将视频保存到PeachHub应用内存储区，而不是世界书
      savePeachhubVideoToStorage(peachhubData);

      console.log('PeachHub内容解析完成，数据:', peachhubData);
    }

