    async function performPeachhubSearch() {
      const searchTerm = peachhubSearchInput.value.trim();
      if (!searchTerm) return;

      try {
        console.log('PeachHub搜索:', searchTerm);

        // 在本地存储中搜索
        const titleResults = PeachhubStorage.searchByTitle(searchTerm);
        const tagResults = PeachhubStorage.searchByTag(searchTerm);

        // 合并搜索结果，去重
        const allResults = [...titleResults, ...tagResults];
        const uniqueResults = allResults.filter((video, index, self) => 
          index === self.findIndex(v => v.id === video.id)
        );

        console.log(`搜索"${searchTerm}"找到${uniqueResults.length}个结果`);

        // 显示搜索结果
        displaySearchResults(searchTerm, uniqueResults);

        // 搜索是纯界面操作，不需要发送请求
        console.log(`PeachHub搜索"${searchTerm}"，找到${uniqueResults.length}个结果`);

        peachhubSearchInput.value = '';
      } catch (error) {
        console.error('发送PeachHub搜索请求时出错:', error);
      }
    }

