          checkbox.addEventListener('change', function() {
            updateOverlayVisibility(this, overlay);

            // 如果取消勾选预览图AI，允许手动选择
            if (checkboxId === 'aiPreview' && !this.checked) {
              const uploadImage = document.getElementById('uploadImage');
              uploadImage.style.cursor = 'pointer';
            } else if (checkboxId === 'aiPreview' && this.checked) {
              const uploadImage = document.getElementById('uploadImage');
              uploadImage.style.cursor = 'default';
            }
