    // 开始上传流程
    async function startUpload(title, description, tags) {
      const uploadBtn = document.getElementById('uploadBtn');
      const uploadProgress = document.getElementById('uploadProgress');
      const progressFill = document.getElementById('progressFill');
      const progressText = document.getElementById('progressText');

      // 禁用上传按钮
      uploadBtn.disabled = true;
      uploadBtn.style.opacity = '0.6';

      // 显示进度条
      uploadProgress.style.display = 'block';

      try {
        // 发送上传请求
        const uploadData = {
          title: title,
          description: description,
          tags: tags
        };

        const request = `/trigger <Request: {{user}}在PeachHub上传视频：标题"${title}"，描述"${description}"，标签"${tags}">`;

        // 模拟上传进度
        let progress = 0;
        const progressInterval = setInterval(() => {
          progress += Math.random() * 20;
          if (progress > 100) progress = 100;

          progressFill.style.width = `${progress}%`;
          progressText.textContent = `上传中... ${Math.floor(progress)}%`;

          if (progress >= 100) {
            clearInterval(progressInterval);
            setTimeout(() => {
              finishUpload();
            }, 500);
          }
        }, 200);

        // 发送请求
        if (typeof triggerSlash === 'function') {
          await triggerSlash(request);
        } else {
          console.log('PeachHub上传请求:', request);
        }

      } catch (error) {
        console.error('上传失败:', error);
        alert('上传失败，请稍后重试');
        resetUploadInterface();
      }
    }

