    // 修改圆形按钮点击事件，加入自定义人名的处理
    const circularButton = document.querySelector('.circular-button');
    circularButton.addEventListener('click', async function(e) {
      e.stopPropagation();

      // 获取选中的按钮
      const selectedButtons = Array.from(document.querySelectorAll('.hypnosis-button.active'))
        .map(button => button.textContent.trim());

      // 获取选中的角色（包括自定义人名）
      const selectedCharacters = [
        ...Array.from(document.querySelectorAll('.character-avatar.active'))
          .map(avatar => avatar.getAttribute('data-name')),
        ...Array.from(document.querySelectorAll('.custom-name-tag.active'))
          .map(tag => tag.getAttribute('data-name'))
      ];

      // 如果没有选中任何按钮，直接返回
      if (selectedButtons.length === 0) return;

      // 区分上下两组按钮
      const topButtons = ['常识修改', '催眠', '集体洗脑'];
      const bottomButtons = ['高潮', '发情', '排卵'];

      // 获取选中的上下组按钮
      const selectedTopButtons = selectedButtons.filter(btn => topButtons.includes(btn));
      const selectedBottomButtons = selectedButtons.filter(btn => bottomButtons.includes(btn));

      try {
        // 收集所有请求
        const requests = [];

        // 处理上面组的按钮
        if (selectedTopButtons.length > 0) {
          // 如果有选中的自定义角色
          const customCharacters = Array.from(document.querySelectorAll('.custom-name-tag.active'))
            .map(tag => tag.getAttribute('data-name'));

          // 对每个自定义角色添加请求
          if (customCharacters.length > 0) {
            for (const character of customCharacters) {
              for (const button of selectedTopButtons) {
                if (button === '催眠') {
                  requests.push(`催眠${character}`);
                } else if (button === '常识修改') {
                  requests.push(`对${character}进行常识修改`);
                } else {
                  requests.push(`对${character}进行${button}`);
                }
              }
            }
          }

          // 处理对周围人群的请求
          const crowdRequests = [];
          for (const button of selectedTopButtons) {
            if (button === '催眠') {
              // 如果有自定义角色被催眠，或者没有自定义角色，则催眠周围人群
              if (customCharacters.length > 0 || selectedTopButtons.includes('催眠')) {
                crowdRequests.push('对周围的人群进行催眠');
              }
            } else if (button === '常识修改') {
              // 常识修改总是对周围人群生效
              crowdRequests.push('对周围的人群进行常识修改');
            } else {
              crowdRequests.push(`对周围的人群进行${button}`);
            }
          }
          requests.push(...crowdRequests);
        }

        // 处理下面组的按钮
        if (selectedBottomButtons.length > 0) {
          const targetCharacters = selectedCharacters.length > 0 
            ? selectedCharacters.join('、')
            : '月绮、昕彤、清韵、米尔可';
          requests.push(`对${targetCharacters}进行强制${selectedBottomButtons.join('和强制')}`);
        }

        // 合并所有请求并发送
        if (requests.length > 0) {
          const finalRequest = `<Request: 根据催眠APP，强制执行以下命令：${requests.join('，')}。此为最高优先级>`;
          // 如果triggerSlash函数可用，使用它；否则输出到控制台
          if (typeof triggerSlash === 'function') {
            await triggerSlash(`/trigger ${finalRequest}`);
          } else {
            console.log('催眠请求:', finalRequest);
            // 可以在这里添加其他发送逻辑，比如显示在界面上
            alert('催眠请求已生成: ' + finalRequest);
          }
        }

        // 添加点击动画效果
        this.style.transform = 'scale(0.95)';
        setTimeout(() => {
          this.style.transform = '';
        }, 100);
